\(\cdot\)
Figure C1.1. The baseline path with the design chosen, by country

import {pathGrid, control, checkboxes, COUNTRIES, countryStyle, OUTCOMES} from "./assets/oa.js"
escPaths = FileAttachment("_generated/data/ESC_Paths.csv").csv({typed: true})
PATHVARS = [["Pension design θ", "theta"], ["Tax rate", "tau"], ["Savings over GDP", "sr"], ["Workweek", "workweek"]]
COSTS = [["the U.S. one for all", "US"], ["each country's own", "own"]]
NAME = ({US: "U.S.", UK: "UK", FR: "France"})
// One country's baseline path at rho = 1 under the paper's cost and the selected parameter, the U.S. one or its own.
countryPath = (country, cost) =&gt; escPaths.filter(d =&gt; (d.source === "main" || d.source === "host")
  && d.country === country && d.spec === "size" && d.rho === 1 && d.wedgeFrom === cost)
series = (rows, variable, reading) =&gt; rows.filter(d =&gt; d.variable === variable)
  .map(d =&gt; ({year: d.year, value: d[reading]})).sort((a, b) =&gt; a.year - b.year)
viewof c1Countries = checkboxes(COUNTRIES, {key: "countries", label: "Countries"})
viewof c1Var = control("select", PATHVARS, {key: "variable", label: "Beside workers per retiree", value: "theta"})
viewof c1Cost = control("radio", COSTS, {key: "cost", label: "Cost parameter", value: "US"})
{
  const lines = v =&gt; c1Countries.map(c =&gt; {
    const st = countryStyle(c);
    return {label: NAME[c], colour: st.colour, symbol: st.symbol,
            records: series(countryPath(c, c1Cost), v, v === "nu" ? "pinned" : "chosen")};
  });
  const observed = c1Var === "theta" ? c1Countries.map(c =&gt; {
    const r = countryPath(c, c1Cost).find(d =&gt; d.variable === "theta" && d.year === 2020);
    return r ? {year: 2020, value: r.pinned, colour: countryStyle(c).colour, text: `${NAME[c]}, observed design: ${r.pinned.toFixed(3)}`} : null;
  }).filter(d =&gt; d) : [];
  const items = c1Countries.map(c =&gt; ({label: NAME[c], colour: countryStyle(c).colour, shape: "line"}));
  if (observed.length) items.push({label: "observed design", colour: "#52514e", shape: "open"});
  return pathGrid([{title: "Workers per retiree ν", variable: "nu", lines: lines("nu"), rule: 2020, ruleLabel: "calibration"},
                   {title: OUTCOMES[c1Var].level, variable: c1Var, lines: lines(c1Var), rule: 2020,
                    ruleLabel: "calibration", observed}],
                  items, {width});
}














































































\(\cdot\)
Note: Log preferences (\(\rho = 1\)). Each country keeps its own calibration and demography; the cost parameter is the U.S. one or the country’s own, as selected, where one re-elects its observed design. A design chosen at one date applies from the following one. Open markers are the observed designs.Data: the figure’s data (csv) · SourceReads:data/USMain_test.xlsxresults/esc/escCalibration.csvresults/esc/escCalibrationCRRA.csvresults/esc/escPath.csvresults/esc/escPathCRRA.csvresults/esc/escPathHost.csvresults/esc/escXiRobustness.csvresults/paper/usCalibrationSummary.csvBuilt by siteData.escPaths (python/paper) at commit 4d49d90. Rebuild: .venv\Scripts\python.exe python\paper\build.py --only ESC_Paths, then build.py --site.

The design chosen and the design pinned
With the design pinned at its observed value, each country’s path is that of section 6 with the cost in place. After 2020 the tax rate with the design chosen lies above the pinned path in every country and under either parameter, consistent with the hump of C2: at a given demography the tax rate peaks close to the design the electorate chooses, so a design pinned away from that choice, on either side, carries a lower one. At each country’s own parameter, the U.S. included, the chosen design rises above the observed one after 2020 as the population ages, and the tax rate lies only slightly above the pinned path. Under the U.S. parameter the UK’s chosen design lies above its observed one throughout and France’s below it, and the gap in the tax rate is largest in the UK.

\(\cdot\)
Figure C1.2. The baseline path with the design chosen and with it pinned

viewof c1bCountry = control("radio", COUNTRIES, {key: "country", label: "Country", value: "US"})
viewof c1bVar = control("select", PATHVARS, {key: "variable2", label: "Beside workers per retiree", value: "theta"})
viewof c1bCost = control("radio", COSTS, {key: "cost2", label: "Cost parameter", value: "US"})
{
  const rows = countryPath(c1bCountry, c1bCost);
  const st = countryStyle(c1bCountry);
  const both = v =&gt; [
    {label: NAME[c1bCountry] + ", design chosen", colour: st.colour, symbol: st.symbol,
     records: series(rows, v, "chosen")},
    {label: NAME[c1bCountry] + ", design pinned", colour: st.colour, symbol: st.symbol, dashed: true,
     records: series(rows, v, "pinned")}];
  const items = [{label: "design chosen", colour: st.colour, shape: "line"},
                 {label: "design pinned at the observed value", colour: st.colour, shape: "line", dashed: true}];
  return pathGrid([{title: "Workers per retiree ν", variable: "nu", rule: 2020, ruleLabel: "calibration",
                    lines: [{label: NAME[c1bCountry], colour: st.colour, symbol: st.symbol, records: series(rows, "nu", "chosen")}]},
                   {title: OUTCOMES[c1bVar].level, variable: c1bVar, lines: both(c1bVar), rule: 2020, ruleLabel: "calibration"}],
                  items, {width});
}





























\(\cdot\)
Note: Log preferences (\(\rho = 1\)). Pinned holds the design at the country’s observed value throughout, under the same cost.Data: the figure’s data (csv) · SourceReads:data/USMain_test.xlsxresults/esc/escCalibration.csvresults/esc/escCalibrationCRRA.csvresults/esc/escPath.csvresults/esc/escPathCRRA.csvresults/esc/escPathHost.csvresults/esc/escXiRobustness.csvresults/paper/usCalibrationSummary.csvBuilt by siteData.escPaths (python/paper) at commit 4d49d90. Rebuild: .venv\Scripts\python.exe python\paper\build.py --only ESC_Paths, then build.py --site.

The baseline path across the elasticities
Along the baseline path the chosen design rises with ageing at every ρ and every ξ. Across the Frisch elasticity the paths nearly coincide. Across the IES the design reaches a similar level by 2110, and before 2020 it lies below the observed design at every IES, by more the higher the IES.

\(\cdot\)
Figure C3.2. The baseline path across the intertemporal and the Frisch elasticity, U.S.

PATHVARS = [["Pension design θ", "theta"], ["Tax rate", "tau"], ["Savings over GDP", "sr"], ["Workweek", "workweek"]]
viewof c4pAcross = control("radio", ACROSS, {key: "across2", label: "Compare across", value: "rho"})
viewof c4pVar = control("select", PATHVARS, {key: "variable", label: "Beside workers per retiree", value: "theta"})
viewof c4pRead = control("radio", [["design chosen", "chosen"], ["design pinned", "pinned"]], {key: "reading", label: "Reading", value: "chosen"})
{
  const spec = c4pAcross === "rho" ? RHO : XI;
  const colours = seriesColours(spec.values);
  const rows = escPaths.filter(d =&gt; d.country === "US" && d.spec === "size" && d.wedgeFrom === "US"
    && (c4pAcross === "rho" ? d.source === "main" : d.source === "xi"));
  const lines = v =&gt; spec.values.map((s, i) =&gt; ({label: spec.labels[i], colour: colours.get(s),
    records: rows.filter(d =&gt; d.variable === v && Math.abs(d[spec.field] - s) &lt; 1e-9)
                 .map(d =&gt; ({year: d.year, value: v === "nu" ? d.chosen : d[c4pRead]})).sort((a, b) =&gt; a.year - b.year)}));
  return pathGrid([{title: "Workers per retiree ν", variable: "nu", lines: lines("nu").slice(0, 1).map(l =&gt; ({...l, colour: "#52514e", label: "U.S."})),
                    rule: 2020, ruleLabel: "calibration"},
                   {title: OUTCOMES[c4pVar].level, variable: c4pVar, lines: lines(c4pVar), rule: 2020, ruleLabel: "calibration"}],
                  spec.values.map((s, i) =&gt; ({label: spec.labels[i], colour: colours.get(s), shape: "line"})), {width});
}




































